    const t0 = countTable(table);
    // counts scaled by 2^-k (k even) where the total is beyond 2^±250: C and D grow as the square of the total and
    // (C + D)^2 as its fourth power ([[1e80, 1e79], [1e79, 1e80]] overflowed to ase 0, [[1e160, 1], [1, 1e160]] to
    // gamma NaN). Gamma does not depend on the scale and ase goes with its inverse square root
    const total = ddSumOf(t0.flat())[0];
