    C = [C[0] / 2, C[1] / 2];
    D = [D[0] / 2, D[1] / 2];
    const CD = ddAdd(C, D);
    const gamma = ddDiv(ddSub(C, D), CD)[0];
    // sigma^2 = sum x psi^2 - (sum x psi)^2; the second sum is 0 in the mathematics (and below 1e-30 as DescTools
    // computes it), so it is left out. psi = 2 (D Pc - C Pd) / (C + D)^2 in double-double: the difference cancels where
    // one count dominates ([[1e17, 1, 2], [3, 4, 5], [6, 7, 8]] gave ase 0 for 4.0229e-17)
    const den = ddMul(CD, CD);
    const psi = t.map((row, i) => row.map((_, j) => 2 * ddDiv(ddSub(ddMul(D, pc[i][j]), ddMul(C, pd[i][j])), den)[0]));
    // the squares relative to a power of 2 near the largest |psi| (they can fall below the doubles: ase 2.8e-320 of
    // [[1e160, 1], [1, 1e160]])
    const top = Math.max(...psi.flat().map(Math.abs));
